import{_ as s,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const p="/img/average-concept.svg",g=JSON.parse('{"title":"奥数精讲：平均数问题一（四年级）","description":"深入理解平均数的概念，掌握“移多补少”和“公式法”两种解题策略，学会解决变动中的平均数难题。","frontmatter":{"title":"奥数精讲：平均数问题一（四年级）","date":"2026-02-28T10:00:00.000Z","categories":["数学"],"tags":["平均数","移多补少","四年级"],"description":"深入理解平均数的概念，掌握“移多补少”和“公式法”两种解题策略，学会解决变动中的平均数难题。"},"headers":[],"relativePath":"posts/primary-math-olympiad-average-1.md","filePath":"posts/primary-math-olympiad-average-1.md","lastUpdated":null}'),l={name:"posts/primary-math-olympiad-average-1.md"};function r(o,a,e,i,c,h){return n(),m("div",null,[...a[0]||(a[0]=[t('<h1 id="平均数问题-寻找平衡的点" tabindex="-1">平均数问题：寻找平衡的点 <a class="header-anchor" href="#平均数问题-寻找平衡的点" aria-label="Permalink to &quot;平均数问题：寻找平衡的点&quot;">​</a></h1><p>在数学中，<strong>平均数</strong>反映了一组数据的集中趋势。通俗地说，就是把几个不相等的数，通过“移多补少”，变得一样多。那个“一样多”的数就是这组数的平均数。</p><hr><h2 id="一、-核心概念与公式" tabindex="-1">一、 核心概念与公式 <a class="header-anchor" href="#一、-核心概念与公式" aria-label="Permalink to &quot;一、 核心概念与公式&quot;">​</a></h2><h3 id="【两种思考方法】" tabindex="-1">【两种思考方法】 <a class="header-anchor" href="#【两种思考方法】" aria-label="Permalink to &quot;【两种思考方法】&quot;">​</a></h3><ol><li><strong>移多补少法：</strong> 想象一排高低不一的水柱，把高的往低的地方倒，直到水面一样平。</li><li><strong>公式法：</strong> 算出总和，再平摊到每一份。</li></ol><h3 id="【核心公式】" tabindex="-1">【核心公式】 <a class="header-anchor" href="#【核心公式】" aria-label="Permalink to &quot;【核心公式】&quot;">​</a></h3><ul><li><strong>平均数 = 总和 ÷ 总份数</strong></li><li><strong>总和 = 平均数 × 总份数</strong></li><li><strong>总份数 = 总和 ÷ 平均数</strong></li></ul><h3 id="【示例-1】" tabindex="-1">【示例 1】 <a class="header-anchor" href="#【示例-1】" aria-label="Permalink to &quot;【示例 1】&quot;">​</a></h3><p><strong>题目：</strong> 小明三场数学小测验的分数分别是 88 分、92 分、90 分。求他的平均成绩。</p><p><img src="'+p+'" alt="平均数概念图解"></p><p><strong>解析过程：</strong></p><ol><li><strong>方法一（移多补少）：</strong> 92 分比 90 分多 2 分，把这 2 分补给 88 分，88 变成 90。这样三场都变成了 90 分。所以平均数是 90。</li><li><strong>方法二（公式法）：</strong><ul><li>总分 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>8</mn><mn>8</mn><mo>+</mo><mn>9</mn><mn>2</mn><mo>+</mo><mn>9</mn><mn>0</mn><mo>=</mo><mn>2</mn><mn>7</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">= 88 + 92 + 90 = 270</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">8</span><span class="mord mathrm">8</span><span class="mbin">+</span><span class="mord mathrm">9</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">9</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">7</span><span class="mord mathrm">0</span></span></span></span>（分）。</li><li>总场数 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>3</mn></mrow><annotation encoding="application/x-tex">= 3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">3</span></span></span></span>。</li><li>平均分 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>2</mn><mn>7</mn><mn>0</mn><mo>÷</mo><mn>3</mn><mo>=</mo><mn>9</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">= 270 \\div 3 = 90</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">7</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">9</span><span class="mord mathrm">0</span></span></span></span>（分）。</li></ul></li></ol><hr><h2 id="二、-引导性思考-如何应对-变动-的平均数" tabindex="-1">二、 引导性思考：如何应对“变动”的平均数？ <a class="header-anchor" href="#二、-引导性思考-如何应对-变动-的平均数" aria-label="Permalink to &quot;二、 引导性思考：如何应对“变动”的平均数？&quot;">​</a></h2><p>如果增加一个数，平均数会怎么变？ <strong>思考逻辑：</strong></p><ul><li>如果新增加的数<strong>大于</strong>原平均数，新的平均数会<strong>上升</strong>。</li><li>如果新增加的数<strong>小于</strong>原平均数，新的平均数会<strong>下降</strong>。</li><li>如果新增加的数<strong>等于</strong>原平均数，新的平均数<strong>不变</strong>。</li></ul><hr><h2 id="三、-引申思考-生活中的平均数陷阱" tabindex="-1">三、 引申思考：生活中的平均数陷阱 <a class="header-anchor" href="#三、-引申思考-生活中的平均数陷阱" aria-label="Permalink to &quot;三、 引申思考：生活中的平均数陷阱&quot;">​</a></h2><ul><li><strong>姚明的身高：</strong> 如果姚明来到我们班，全班的平均身高会猛增，但这并不代表我们每个人都变高了。这就是平均数容易被“极端大数”拉高的特点。</li><li><strong>工资平均水平：</strong> 同理，如果少数人收入极高，平均工资也会显得很高。</li></ul><hr><h2 id="四、-举一反三-实战练习" tabindex="-1">四、 举一反三：实战练习 <a class="header-anchor" href="#四、-举一反三-实战练习" aria-label="Permalink to &quot;四、 举一反三：实战练习&quot;">​</a></h2><ol><li><p><strong>基础练习：</strong> 小红、小刚和小华三人的年龄分别是 9 岁、11 岁、13 岁。求他们的平均年龄。 <em>提示：用公式法计算。</em></p></li><li><p><strong>进阶练习（求总和）：</strong> 5 个数的平均数是 20。如果把这 5 个数加起来，总和是多少？ <em>提示：总和 = 平均数 × 5。</em></p></li><li><p><strong>挑战练习（动态变化）：</strong> 小明前 4 次考试的平均成绩是 90 分。第 5 次考试得了 95 分。请问他这 5 次考试的平均成绩是多少？ <em>提示：先求前 4 次的总分，加上第 5 次的分数，再除以 5。</em></p></li></ol><hr><p><strong>解析预览：</strong></p><ol><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>9</mn><mo>+</mo><mn>1</mn><mn>1</mn><mo>+</mo><mn>1</mn><mn>3</mn><mo>)</mo><mo>÷</mo><mn>3</mn><mo>=</mo><mn>3</mn><mn>3</mn><mo>÷</mo><mn>3</mn><mo>=</mo><mn>1</mn><mn>1</mn></mrow><annotation encoding="application/x-tex">(9 + 11 + 13) \\div 3 = 33 \\div 3 = 11</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">9</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">3</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">3</span><span class="mbin">÷</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span></span></span></span> 岁。</li><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>×</mo><mn>5</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">20 \\times 5 = 100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>。</li><li>前 4 次总分：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mn>0</mn><mo>×</mo><mn>4</mn><mo>=</mo><mn>3</mn><mn>6</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">90 \\times 4 = 360</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span><span class="mord mathrm">0</span></span></span></span> 分。5 次总分：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>6</mn><mn>0</mn><mo>+</mo><mn>9</mn><mn>5</mn><mo>=</mo><mn>4</mn><mn>5</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">360 + 95 = 455</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">6</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">9</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mord mathrm">5</span></span></span></span> 分。5 次平均分：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>5</mn><mn>5</mn><mo>÷</mo><mn>5</mn><mo>=</mo><mn>9</mn><mn>1</mn></mrow><annotation encoding="application/x-tex">455 \\div 5 = 91</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mord mathrm">5</span><span class="mbin">÷</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">9</span><span class="mord mathrm">1</span></span></span></span> 分。 <em>(或者：第 5 次比平均分多出的 5 分，平摊到 5 次，每场加 1 分。90 + 1 = 91。)</em></li></ol>',26)])])}const u=s(l,[["render",r]]);export{g as __pageData,u as default};
